function arr(v) { return Array.isArray(v) ? v : []; }

function splitMessage(text, maxLen = 3600) {
  const chunks = [];
  let rest = text;
  while (rest.length > maxLen) {
    let cut = rest.lastIndexOf('\n\n', maxLen);
    if (cut < 1000) cut = rest.lastIndexOf('\n', maxLen);
    if (cut < 1000) cut = maxLen;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) chunks.push(rest);
  return chunks;
}

function lineObjectList(list, fields) {
  let out = '';
  arr(list).forEach((item, i) => {
    if (typeof item === 'string') out += `${i + 1}. ${item}\n`;
    else out += `${i + 1}. ${fields.map(f => item?.[f]).filter(Boolean).join(' — ') || JSON.stringify(item)}\n`;
  });
  return out;
}

