      const ents = arr(s.entities).slice(0, 12).map(e => typeof e === 'string' ? e : `${e.name || '-'} (${e.priority || '-'})`);
      text += `Сущности: ${ents.join(', ')}\n`;
    }
    if (arr(s.visual_elements).length) text += `Визуальные элементы: ${arr(s.visual_elements).join(', ')}\n`;
    if (arr(s.key_takeaways).length) text += `Key takeaways: ${arr(s.key_takeaways).join('; ')}\n`;
    text += `Заметки: ${s.copywriter_notes || '-'}\n\n`;
  });

  if (arr(result.entity_connections).length) {
    text += 'Entity connections:\n';
    text += lineObjectList(result.entity_connections, ['from', 'to', 'reason']);
    text += '\n';
  }

  if (arr(result.faq).length) {
    text += 'FAQ:\n';
