        if (item.answer_goal) text += `   Цель ответа: ${item.answer_goal}\n`;
      }
    });
    text += '\n';
  }

  if (result.cta) text += `CTA:\n${result.cta}\n\n`;
  if (result.qa) {
    text += `QA: ${result.qa.verdict || '-'}\n`;
    if (result.qa.summary) text += `Резюме QA: ${result.qa.summary}\n`;
  }
}

