function extractContent(input) {
  if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
  if (input.body?.choices?.[0]?.message?.content) return input.body.choices[0].message.content;
  return '{}';
}

function parseJsonLoose(value) {
  if (typeof value !== 'string') return value || {};
  let text = value.trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}

function safeParse(value) {
  try {
    return parseJsonLoose(value);
  } catch (e) {
    return {
      mode: 'factcheck',
      verdict: 'reject',
      summary: 'Ошибка парсинга factcheck JSON',
      risky_claims: [String(e.message || e)],
      unsupported_claims: [],
      recommended_removals: [],
      missing_data: []
    };
  }
}

